"""
THIS FILE IS NOT PART OF THE PIPELINE.
It performs comparisons on existing outputs.
"""

import sys
import warnings
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
sys.dont_write_bytecode = True

import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
import numpy as np
import pandas as pd
from sklearn.metrics import mean_absolute_error, mean_squared_error, r2_score

import config

warnings.filterwarnings("ignore")

# 8 main parameters generated by the baseline camera method
MAIN_TARGETS = ["Step_UGS", "Stride_UGS", "Cadence_UGS", "Velocity_UGS",
                "Step_FGS", "Stride_FGS", "Cadence_FGS", "Velocity_FGS"]

MAIN_MODEL = "Ridge"
PRIMARY_TRACK = "All_Participants"

OUT_FOLDER = config.THESIS_TABLES  

# =====================================================================
# METRIC AIDS
# =====================================================================

def error_metrics(actual, predicted):
    """Sensor vs Prediction Error Metrics for a Parameter"""
    actual = np.asarray(actual, dtype=float)
    predicted = np.asarray(predicted, dtype=float)
    mask = ~(np.isnan(actual) | np.isnan(predicted))
    actual, predicted = actual[mask], predicted[mask]
    percent_error = np.abs((actual - predicted) / actual) * 100
    return {
        "N": len(actual),
        "Mean_Sensor": actual.mean(),
        "Mean_Pred": predicted.mean(),
        "R2": r2_score(actual, predicted),
        "MAE": mean_absolute_error(actual, predicted),
        "RMSE": np.sqrt(mean_squared_error(actual, predicted)),
        "MAPE": percent_error.mean(),
        "MedAPE": np.median(percent_error),
    }


def unit_of(target):
    return config.unit_of(target)


def readable(target):
    return config.readable_name(target).replace(" gait", "")


# =====================================================================
# TABLES 1 AND 2 - BASELINE vs SENSOR
# =====================================================================

def baseline_summary(sensor_df, baseline_df, keep_ids=None):
    """
    Baseline camera method error relative to the sensor for each main parameter
    """
    merged = pd.merge(sensor_df, baseline_df, on="ID", suffixes=("_sensor", "_base"))
    if keep_ids is not None:
        merged = merged[merged["ID"].isin(keep_ids)]

    rows = []
    for target in MAIN_TARGETS:
        m = error_metrics(merged[f"{target}_sensor"], merged[f"{target}_base"])
        rows.append({
            "Parameter": readable(target),
            "Unit": unit_of(target),
            "N": m["N"],
            "Mean_Sensor_Value": round(m["Mean_Sensor"], 3),
            "Mean_Baseline_Prediction": round(m["Mean_Pred"], 3),
            "R2": round(m["R2"], 3),
            "MAE": round(m["MAE"], 3),
            "RMSE": round(m["RMSE"], 3),
            "MAPE_Percent": round(m["MAPE"], 1),
            "MedAPE_Percent": round(m["MedAPE"], 1),
        })
    return pd.DataFrame(rows)


# =====================================================================
# TABLE 3 - SENSOR vs BASELINE vs MODEL
# =====================================================================

def baseline_vs_model_summary(predictions, baseline_df, stability):
    """
    It places the baseline and model errors side-by-side for each key parameter.
    """
    baseline_i = baseline_df.set_index("ID")
    r2_lookup = (stability[stability["Track"] == PRIMARY_TRACK]
                 .set_index("Target_Code")["R2_Mean"])
    rid = predictions[(predictions["Model"] == MAIN_MODEL)
                      & (predictions["Track"] == PRIMARY_TRACK)]

    rows = []
    for target in MAIN_TARGETS:
        group = rid[rid["Target"] == target].set_index("Participant_ID")
        if group.empty:
            continue
        sensor = group["Sensor_Value"]
        model = group["Model_Prediction"]
        model_pe = np.abs((sensor - model) / sensor) * 100

        common = group.index.intersection(baseline_i.index)
        base = baseline_i.loc[common, target]
        sensor_c = sensor.loc[common]
        model_c = model.loc[common]
        base_err = (sensor_c - base).abs()
        model_err = (sensor_c - model_c).abs()
        base_pe = np.abs((sensor_c - base) / sensor_c) * 100

        base_mae = round(base_err.mean(), 4)
        model_mae = round(model_err.mean(), 4)
        improvement = (base_mae - model_mae) / base_mae * 100 if base_mae > 0 else np.nan

        rows.append({
            "Parameter": readable(target),
            "Unit": unit_of(target),
            "N": len(group),
            "Mean_Sensor_Value": round(sensor.mean(), 3),
            "Mean_Baseline_Prediction": round(base.mean(), 3),
            "Mean_Model_Prediction": round(model.mean(), 3),
            "Baseline_R2": round(r2_score(sensor_c, base), 3),
            "Baseline_MAE": round(base_err.mean(), 3),
            "Baseline_RMSE": round(np.sqrt((base_err ** 2).mean()), 3),
            "Baseline_MAPE_Percent": round(base_pe.mean(), 1),
            "Baseline_MedAPE_Percent": round(base_pe.median(), 1),
            "Model_R2": round(float(r2_lookup[target]), 3),
            "Model_MAE": round(model_err.mean(), 3),
            "Model_RMSE": round(np.sqrt((model_err ** 2).mean()), 3),
            "Model_MAPE_Percent": round(model_pe.mean(), 1),
            "Model_MedAPE_Percent": round(np.median(model_pe), 1),
            "Improvement_Percent": round(improvement, 1),
            "Model_Is_Better": "Yes" if model_mae < base_mae else "No",
        })
    return pd.DataFrame(rows)


# =====================================================================
# PNG DRAWING
# =====================================================================

def render_png(df, title, path, fontsize=9):
    """It saves the DataFrame as a clean table view."""
    display = df.copy()
    display.columns = [c.replace("_Percent", "_%").replace("_", "\n")
                       for c in display.columns]
    n_rows, n_cols = display.shape

    figure, axis = plt.subplots(figsize=(min(1.6 + n_cols * 1.5, 30),
                                         1.8 + n_rows * 0.45))
    axis.axis("off")
    table = axis.table(cellText=display.values, colLabels=display.columns,
                       cellLoc="center", loc="center")
    table.auto_set_font_size(False)
    table.set_fontsize(fontsize)
    table.scale(1, 1.6)

    for (r, c), cell in table.get_celld().items():
        if r == 0:
            cell.set_facecolor("#2C3E50")
            cell.set_text_props(color="white", fontweight="bold")
            cell.set_height(cell.get_height() * 2.4)
        else:
            cell.set_facecolor("#F4F6F7" if r % 2 else "#FFFFFF")
        cell.set_edgecolor("#BDC3C7")

    axis.set_title(title, fontsize=fontsize + 4, fontweight="bold", pad=18)
    figure.tight_layout()
    figure.savefig(path, dpi=200, bbox_inches="tight", facecolor="white")
    plt.close(figure)
    print(f"  [SAVED] {path.name}")


def save_both(df, stem, title, fontsize=9):
    """It saves the DataFrame as both a CSV and a PNG file."""
    OUT_FOLDER.mkdir(parents=True, exist_ok=True)
    df.to_csv(OUT_FOLDER / f"{stem}.csv", index=False, encoding="utf-8-sig")
    print(f"  [SAVED] {stem}.csv  ({len(df)} rows)")
    render_png(df, title, OUT_FOLDER / f"{stem}.png", fontsize)


# =====================================================================
# MAIN FLOW
# =====================================================================

def main():
    needed = [config.SENSOR_MEASUREMENTS, config.BASELINE_ESTIMATES,
              config.CHECK_5_MODEL_INPUT, config.CHECK_6_PREDICTIONS,
              config.CHECK_7_STABILITY]
    missing = [str(p) for p in needed if not p.exists()]
    if missing:
        print("[ERROR] Missing input file(s):")
        for p in missing:
            print(f"        - {p}")
        print("        Run the pipeline first (run_pipeline.py).")
        return

    print("=" * 70)
    print("   THREE-TABLE EVALUATION REPORT  (PNG + CSV)")
    print("=" * 70)

    sensor = pd.read_csv(config.SENSOR_MEASUREMENTS)
    baseline = pd.read_csv(config.BASELINE_ESTIMATES)
    predictions = pd.read_csv(config.CHECK_6_PREDICTIONS)
    stability = pd.read_csv(config.CHECK_7_STABILITY)
    final_ids = pd.read_csv(config.CHECK_5_MODEL_INPUT)["Participant_ID"].unique()

    # --- Tablo 1: tum veri ---
    table1 = baseline_summary(sensor, baseline, keep_ids=None)
    n1 = int(table1["N"].max())
    save_both(table1, "Eval_Table1_Baseline_AllData",
              f"Table 1 - Baseline Camera Method vs Sensor  (all data, n={n1})")

    # --- Tablo 2: nihai orneklem ---
    table2 = baseline_summary(sensor, baseline, keep_ids=final_ids)
    n2 = int(table2["N"].max())
    save_both(table2, "Eval_Table2_Baseline_FinalSample",
              f"Table 2 - Baseline Camera Method vs Sensor  (final sample, n={n2})")

    # --- Tablo 3: baseline + model ---
    table3 = baseline_vs_model_summary(predictions, baseline, stability)
    n3 = int(table3["N"].max())
    save_both(table3, "Eval_Table3_Baseline_vs_Model",
              f"Table 3 - Sensor vs Baseline vs Model  (final sample, n={n3})",
              fontsize=8)

    print("\n[DONE] 3 tables written as CSV + PNG to:")
    print(f"       {OUT_FOLDER}")


if __name__ == "__main__":
    main()
